{"command":"@'
$files = @(
  'Índice do Vault.md',
  'HOME/Segundo Cérebro/MOC - Segundo Cérebro.md',
  'HOME/O Professor/MOC - O Professor.md',
  'HOME/Cérebro Profissional/MOC - Cérebro Profissional.md',
  'HOME/Kevyn Lucas/MOC - Kevyn Lucas.md',
  'ACIRV/MOC - ACIRV.md'
)
$root = (Get-Location).Path
foreach ($file in $files) {
  $content = Get-Content -Raw $file
  $dir = Split-Path -Parent (Join-Path $root $file)
  $matches = [regex]::Matches($content, '\[\[([^\]|]+)(?:\|[^\]]+)?\]\]')
  foreach ($m in $matches) {
    $target = $m.Groups[1].Value
    $candidates = @()
    if ($target -match '\.[A-Za-z0-9]+$') {
      $candidates += (Join-Path $dir $target)
      $candidates += (Join-Path $root $target)
    } else {
      $candidates += (Join-Path $dir ($target + '.md'))
      $candidates += (Join-Path $root ($target + '.md'))
    }
    if (-not ($candidates | Where-Object { Test-Path $_ } | Select-Object -First 1)) {
      Write-Output "$file :: MISSING :: $target"
    }
  }
}
